#!/usr/bin/env python3
from ta_emss import ta_emss

CELL_ID_START = 5
SIM_VDU_ID_START = 2
AMF_ID_START = 1

if __name__ == "__main__":

    emss1 = ta_emss()
    emss1.setup_emss(bts_id=1, user="vcu1", bts_ip="192.168.100.129", oam_ip="192.168.100.1/24", alias="cu1")
    emss1.xterm_setup(
        # --- XNAP PARAMS ---
        gnbsim_eth_if="eth3",
        gnbsim_ip_addr_mask=24,
        # --- F1AP PARAMS ---
        vdusim_eth_if="eth3",
        vdusim_ip_addr_mask=24,
        init_vdu_gnb_du_id=SIM_VDU_ID_START,
        init_vdu_cell_id_begin=CELL_ID_START,
        # --- NGAP PARAMS ---
        amf_eth_if="eth3",
        amf_ip_addr_mask="24",
        amf_id_start=AMF_ID_START,
        # --- XTERM OPTIONS ---
        verbose=True,
        debug=False,
        # --- Auto Setup ---
        dynamic_setup_ngap=True,
        dynamic_setup_f1ap=True,
        dynamic_setup_xnap=True,
        # dynamic_setup=True,  # sets all dynamic_setup_XXX to True
    )
    emss1.xterm_autostart()  # or emss1.xterm_start(...) for manual control

    # --- BREAK SIMULATION ---
    while (k := input("Press 'q' to stop...")) != "q":
        pass

    emss1.xterm_teardown()
